    Point sorted[n];
    for (int i=0;i<n;i++) sorted[i]=pts[i];
    qsort(sorted, n, sizeof(Point), cmp);

    Point hull[2*n]; int k=0;
    for (int i=0;i<n;i++) { while(k>=2&&cross(hull[k-2],hull[k-1],sorted[i])<=0)k--; hull[k++]=sorted[i]; }
    for (int i=n-2,t=k+1;i>=0;i--) { while(k>=t&&cross(hull[k-2],hull[k-1],sorted[i])<=0)k--; hull[k++]=sorted[i]; }
