#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define MAXN 100
#define MAXV 1000
#define EPS 1e-12

typedef struct {
    double x, y;
} Point;

typedef struct {
    Point pts[MAXV];
    int n;
} Polygon;

int n;
double R;
Point holes[MAXN];
double areas[MAXN];

double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dot(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

double dist2(Point a, Point b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return dx*dx + dy*dy;
}

int cmp_double(double a, double b) {
    if (fabs(a - b) < EPS) return 0;
    return a < b ? -1 : 1;
}

void add_point(Polygon *p, double x, double y) {
    if (p->n > 0 && cmp_double(p->pts[p->n-1].x, x) == 0 && cmp_double(p->pts[p->n-1].y, y) == 0)
        return;
    p->pts[p->n].x = x;
    p->pts[p->n].y = y;
    p->n++;
}

void clip_polygon(Polygon *poly, Point a, Point b) {
    Polygon res;
    res.n = 0;
    if (poly->n == 0) return;
    for (int i = 0; i < poly->n; i++) {
        Point cur = poly->pts[i];
        Point nxt = poly->pts[(i+1) % poly->n];
        double cur_val = cross(a, b, cur);
        double nxt_val = cross(a, b, nxt);
        int cur_in = cmp_double(cur_val, 0) >= 0;
        int nxt_in = cmp_double(nxt_val, 0) >= 0;
        if (cur_in) {
            add_point(&res, cur.x, cur.y);
        }
        if (cur_in != nxt_in) {
            double t = cur_val / (cur_val - nxt_val);
            double ix = cur.x + t * (nxt.x - cur.x);
            double iy = cur.y + t * (nxt.y - cur.y);
            add_point(&res, ix, iy);
        }
    }
    poly->n = res.n;
    for (int i = 0; i < res.n; i++) poly->pts[i] = res.pts[i];
}

double polygon_area(Polygon *p) {
    double area = 0;
    for (int i = 0; i < p->n; i++) {
        int j = (i+1) % p->n;
        area += p->pts[i].x * p->pts[j].y - p->pts[j].x * p->pts[i].y;
    }
    return fabs(area) / 2.0;
}

int main() {
    scanf("%d %lf", &n, &R);
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &holes[i].x, &holes[i].y);
    }

    // For each hole, construct its Voronoi cell clipped to the circle
    for (int i = 0; i < n; i++) {
        Polygon cell;
        // Start with the big circle as a polygon approximation
        int segs = 200;
        cell.n = 0;
        for (int j = 0; j < segs; j++) {
            double ang = 2 * M_PI * j / segs;
            double x = R * cos(ang);
            double y = R * sin(ang);
            add_point(&cell, x, y);
        }

        // Clip by bisectors with all other holes
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            Point mid = { (holes[i].x + holes[j].x) / 2.0, (holes[i].y + holes[j].y) / 2.0 };
            Point dir = { holes[j].y - holes[i].y, holes[i].x - holes[j].x }; // perpendicular to IJ
            Point a = { mid.x - dir.x, mid.y - dir.y };
            Point b = { mid.x + dir.x, mid.y + dir.y };
            // Ensure correct half-plane: the side containing hole i
            if (cross(a, b, holes[i]) < 0) {
                Point tmp = a;
                a = b;
                b = tmp;
            }
            clip_polygon(&cell, a, b);
        }
        areas[i] = polygon_area(&cell);
    }

    double total = M_PI * R * R;
    for (int i = 0; i < n; i++) {
        printf("%.10lf\n", areas[i] / total);
    }

    return 0;
}

