typedef long double ld;

typedef struct {
    ld x, y;
} Point;

static const ld PI = 3.141592653589793238462643383279502884L;
static const ld EPS = 1e-12L;

/*
For very large R, the probability that a random point in the disk falls to hole i
equals the area fraction of the Voronoi cell of hole i inside the disk.

As R -> infinity:
- If a hole is not on the convex hull of all holes, its Voronoi cell is bounded,
  so its probability tends to 0.
- If a hole is a convex hull vertex, its Voronoi cell is an unbounded wedge.
  The asymptotic area fraction equals its exterior angle / (2*pi).

Tie-breaking by smaller index only affects measure-zero boundaries, so it does not
change probabilities.

Thus we only need convex hull vertices and their exterior angles.
If all points are collinear:
- Only the two extreme points have nonzero probability, each 1/2
- If all points coincide, the smallest index gets probability 1
*/

int cmp_point_idx(const void *a, const void *b, void *ctx) {
    Point *p = (Point *)ctx;
    int i = *(const int *)a;
    int j = *(const int *)b;
    if (fabsl(p[i].x - p[j].x) > EPS) return (p[i].x < p[j].x) ? -1 : 1;
    if (fabsl(p[i].y - p[j].y) > EPS) return (p[i].y < p[j].y) ? -1 : 1;
    return (i < j) ? -1 : (i > j);
}

ld cross3(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

ld dot2(ld ax, ld ay, ld bx, ld by) {
    return ax * bx + ay * by;
}

ld norm2(ld x, ld y) {
    return sqrtl(x * x + y * y);
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point *p = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; i++) {
        scanf("%Lf %Lf", &p[i].x, &p[i].y);
    }

    ld *ans = (ld *)calloc(N, sizeof(ld));

    if (N == 1) {
        printf("1.0000000000\n");
        free(p);
        free(ans);
        return 0;
    }

    /* Check if all points coincide */
    int all_same = 1;
    for (int i = 1; i < N; i++) {
        if (fabsl(p[i].x - p[0].x) > EPS || fabsl(p[i].y - p[0].y) > EPS) {
            all_same = 0;
            break;
        }
    }
    if (all_same) {
        ans[0] = 1.0L; /* tie breaks to smallest index */
        for (int i = 0; i < N; i++) {
            printf("%.10Lf\n", ans[i]);
        }
        free(p);
        free(ans);
        return 0;
    }

    int *ord = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) ord[i] = i;

#if defined(__GNUC__) && !defined(__clang__)
    qsort_r(ord, N, sizeof(int), cmp_point_idx, p);
#else
    /* portable fallback using globals via static */
    struct Local {
        Point *p;
    } dummy;
    (void)dummy;
    static Point *gp;
    gp = p;
    int cmp_wrap(const void *a, const void *b) {
        int i = *(const int *)a;
        int j = *(const int *)b;
        if (fabsl(gp[i].x - gp[j].x) > EPS) return (gp[i].x < gp[j].x) ? -1 : 1;
        if (fabsl(gp[i].y - gp[j].y) > EPS) return (gp[i].y < gp[j].y) ? -1 : 1;
        return (i < j) ? -1 : (i > j);
    }
    qsort(ord, N, sizeof(int), cmp_wrap);
#endif

    /* Remove duplicate coordinates; keep only smallest index among duplicates */
    int *uniq = (int *)malloc(sizeof(int) * N);
    int M = 0;
    for (int i = 0; i < N; ) {
        int best = ord[i];
        int j = i + 1;
        while (j < N &&
               fabsl(p[ord[j]].x - p[ord[i]].x) <= EPS &&
               fabsl(p[ord[j]].y - p[ord[i]].y) <= EPS) {
            if (ord[j] < best) best = ord[j];
            j++;
        }
        uniq[M++] = best;
        i = j;
    }

    if (M == 1) {
        ans[uniq[0]] = 1.0L;
        for (int i = 0; i < N; i++) {
            printf("%.10Lf\n", ans[i]);
        }
        free(p); free(ans); free(ord); free(uniq);
        return 0;
    }

    int *hull = (int *)malloc(sizeof(int) * (2 * M + 5));
    int hs = 0;

    /* lower hull */
    for (int i = 0; i < M; i++) {
        int idx = uniq[i];
        while (hs >= 2) {
            Point a = p[hull[hs - 2]];
            Point b = p[hull[hs - 1]];
            Point c = p[idx];
            if (cross3(a, b, c) <= EPS) hs--;
            else break;
        }
        hull[hs++] = idx;
    }

    /* upper hull */
    int lower_size = hs;
    for (int i = M - 2; i >= 0; i--) {
        int idx = uniq[i];
        while (hs > lower_size) {
            Point a = p[hull[hs - 2]];
            Point b = p[hull[hs - 1]];
            Point c = p[idx];
            if (cross3(a, b, c) <= EPS) hs--;
            else break;
        }
        hull[hs++] = idx;
    }

    if (hs > 1) hs--; /* last equals first */

    /* Collinear case: hull has 2 points */
    if (hs == 2) {
        ans[hull[0]] = 0.5L;
        ans[hull[1]] = 0.5L;
        for (int i = 0; i < N; i++) {
            printf("%.10Lf\n", ans[i]);
        }
        free(p); free(ans); free(ord); free(uniq); free(hull);
        return 0;
    }

    for (int i = 0; i < hs; i++) {
        int prv = hull[(i - 1 + hs) % hs];
        int cur = hull[i];
        int nxt = hull[(i + 1) % hs];

        ld v1x = p[prv].x - p[cur].x;
        ld v1y = p[prv].y - p[cur].y;
        ld v2x = p[nxt].x - p[cur].x;
        ld v2y = p[nxt].y - p[cur].y;

        ld len1 = norm2(v1x, v1y);
        ld len2 = norm2(v2x, v2y);
        ld cs = dot2(v1x, v1y, v2x, v2y) / (len1 * len2);
        if (cs > 1) cs = 1;
        if (cs < -1) cs = -1;

        ld interior = acosl(cs);
        ld exterior = PI - interior;
        ans[cur] = exterior / (2.0L * PI);
    }

    for (int i = 0; i < N; i++) {
        printf("%.10Lf\n", ans[i]);
    }

    free(p);
    free(ans);
    free(ord);
    free(uniq);
    free(hull);
    return 0;
}

