#include <bits/stdc++.h>
using namespace std;

using ld = long double;
const ld PI = acosl(-1.0L);
const ld EPS = 1e-12L;

struct Point {
    ld x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long R_input;
    cin >> N >> R_input;
    ld R = (ld)R_input;

    vector<Point> p(N);
    for (int i = 0; i < N; ++i) {
        long long x, y;
        cin >> x >> y;
        p[i] = {(ld)x, (ld)y};
    }

    // For very large R, the probability converges to:
    //   area(unbounded Voronoi cell of i clipped by circle radius R) / (pi R^2)
    // As R -> infinity:
    //   = angle_measure_of_directions_where_i_is_extreme / (2*pi)
    //
    // For a direction u, hole i owns points far away in direction u iff
    // p_i · u > p_j · u for all j != i, with tie broken by smaller index.
    //
    // For fixed i,j:
    //   (p_i - p_j) · u > 0  if i should beat j
    //   (p_i - p_j) · u >= 0 if i < j (tie goes to i)
    //   (p_i - p_j) · u > 0  if i > j (tie goes to j, so strict)
    //
    // Each condition is an interval of angles of length pi.
    // Intersect all such intervals on the circle and measure total length.

    cout << fixed << setprecision(15);

    for (int i = 0; i < N; ++i) {
        vector<pair<ld,int>> events; // angle, +1 start / -1 end on [0,2pi)
        bool impossible = false;
        int base = 0;

        for (int j = 0; j < N; ++j) if (i != j) {
            ld dx = p[i].x - p[j].x;
            ld dy = p[i].y - p[j].y;

            if (fabsl(dx) < EPS && fabsl(dy) < EPS) {
                // Same point.
                // If j < i, then i can never win ties against j.
                if (j < i) {
                    impossible = true;
                    break;
                } else {
                    // j > i imposes no restriction.
                    continue;
                }
            }

            ld alpha = atan2l(dy, dx); // center direction where dot > 0
            ld L = alpha - PI / 2.0L;
            ld RR = alpha + PI / 2.0L;

            // Normalize to [0, 2pi)
            auto norm = [&](ld a) {
                while (a < 0) a += 2.0L * PI;
                while (a >= 2.0L * PI) a -= 2.0L * PI;
                return a;
            };

            ld l = norm(L);
            ld r = norm(RR);

            // Allowed set is a semicircle [l, r] cyclically.
            if (l <= r) {
                events.push_back({l, +1});
                events.push_back({r, -1});
            } else {
                // wraps around: [0,r] U [l,2pi)
                base += 1;
                events.push_back({r, -1});
                events.push_back({l, +1});
            }
        }

        if (impossible) {
            cout << 0.0L << '\n';
            continue;
        }

        if (events.empty()) {
            // Only possible when all other points coincide with i and have larger index.
            cout << 1.0L << '\n';
            continue;
        }

        sort(events.begin(), events.end(), [](const auto& a, const auto& b) {
            if (fabsl(a.first - b.first) > EPS) return a.first < b.first;
            return a.second > b.second; // start before end at same angle
        });

        int need = N - 1;
        int cur = base;
        ld prev = 0.0L;
        ld good = 0.0L;

        int m = events.size();
        for (int k = 0; k < m; ) {
            ld ang = events[k].first;
            if (cur == need && ang > prev) good += ang - prev;

            while (k < m && fabsl(events[k].first - ang) <= EPS) {
                cur += events[k].second;
                ++k;
            }
            prev = ang;
        }
        if (cur == need && 2.0L * PI > prev) good += 2.0L * PI - prev;

        ld ans = good / (2.0L * PI);
        if (ans < 0 && ans > -1e-15L) ans = 0;
        if (ans > 1 && ans < 1 + 1e-15L) ans = 1;
        cout << (double)ans << '\n';
    }

    return 0;
}

import java.util.*;
import java.awt.geom.*;

public class Main {
    static final double EPS = 1e-12;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long R = sc.nextLong();
        long[] x = new long[N];
        long[] y = new long[N];
        for (int i = 0; i < N; i++) {
            x[i] = sc.nextLong();
            y[i] = sc.nextLong();
        }

        double totalArea = Math.PI * R * R;
        double[] probs = new double[N];

        for (int i = 0; i < N; i++) {
            List<Point2D> cell = getBoundingSquare(R);
            for (int j = 0; j < N; j++) {
                if (i == j) continue;
                double mx = (x[i] + x[j]) / 2.0;
                double my = (y[i] + y[j]) / 2.0;
                double dx = x[j] - x[i];
                double dy = y[j] - y[i];
                // Perpendicular bisector: dx*(x - mx) + dy*(y - my) = 0
                // We want side where (x_i,y_i) is closer -> dx*(x - mx) + dy*(y - my) <= 0
                cell = clipPolygon(cell, mx, my, dx, dy);
                if (cell.size() < 3) break;
            }
            // Clip with the big circle
            cell = clipByCircle(cell, R);
            double area = polygonArea(cell);
            probs[i] = area / totalArea;
        }

        for (int i = 0; i < N; i++) {
            System.out.printf("%.15f\n", probs[i]);
        }
    }

    static List<Point2D> getBoundingSquare(double R) {
        double r = R * 2;
        List<Point2D> sq = new ArrayList<>();
        sq.add(new Point2D.Double(-r, -r));
        sq.add(new Point2D.Double(r, -r));
        sq.add(new Point2D.Double(r, r));
        sq.add(new Point2D.Double(-r, r));
        return sq;
    }

    // Clip polygon by half-plane: dx*(x - mx) + dy*(y - my) <= 0
    static List<Point2D> clipPolygon(List<Point2D> poly, double mx, double my, double dx, double dy) {
        List<Point2D> out = new ArrayList<>();
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point2D cur = poly.get(i);
            Point2D nxt = poly.get((i + 1) % n);
            double curVal = dx * (cur.getX() - mx) + dy * (cur.getY() - my);
            double nxtVal = dx * (nxt.getX() - mx) + dy * (nxt.getY() - my);
            boolean curInside = curVal <= EPS;
            boolean nxtInside = nxtVal <= EPS;
            if (curInside) out.add(cur);
            if (curInside != nxtInside) {
                double t = curVal / (curVal - nxtVal);
                out.add(new Point2D.Double(
                    cur.getX() + t * (nxt.getX() - cur.getX()),
                    cur.getY() + t * (nxt.getY() - cur.getY())
                ));
            }
        }
        return out;
    }

    // Clip polygon by the circle x^2 + y^2 <= R^2
    static List<Point2D> clipByCircle(List<Point2D> poly, double R) {
        List<Point2D> out = new ArrayList<>();
        int n = poly.size();
        if (n == 0) return out;
        double R2 = R * R;
        for (int i = 0; i < n; i++) {
            Point2D a = poly.get(i);
            Point2D b = poly.get((i + 1) % n);
            boolean aIn = a.getX() * a.getX() + a.getY() * a.getY() <= R2 + EPS;
            boolean bIn = b.getX() * b.getX() + b.getY() * b.getY() <= R2 + EPS;
            if (aIn) out.add(a);
            if (aIn != bIn) {
                // Line-circle intersection
                double dx = b.getX() - a.getX();
                double dy = b.getY() - a.getY();
                double A = dx * dx + dy * dy;
                double B = 2 * (a.getX() * dx + a.getY() * dy);
                double C = a.getX() * a.getX() + a.getY() * a.getY() - R2;
                double t = (-B + Math.sqrt(B * B - 4 * A * C)) / (2 * A);
                if (t < 0 || t > 1) t = (-B - Math.sqrt(B * B - 4 * A * C)) / (2 * A);
                out.add(new Point2D.Double(a.getX() + t * dx, a.getY() + t * dy));
            }
        }
        return out;
    }

    static double polygonArea(List<Point2D> poly) {
        int n = poly.size();
        if (n < 3) return 0;
        double area = 0;
        for (int i = 0; i < n; i++) {
            Point2D a = poly.get(i);
            Point2D b = poly.get((i + 1) % n);
            area += a.getX() * b.getY() - b.getX() * a.getY();
        }
        return Math.abs(area) / 2.0;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        double[] x = new double[n], y = new double[n];
        for (int i = 0; i < n; i++) { x[i] = sc.nextDouble(); y[i] = sc.nextDouble(); }

        // Convex hull (CCW)
        int[] hull = convexHull(x, y, n);

        double[] prob = new double[n];
        int m = hull.length;
        // For each hull vertex, compute angular range of outward normals
        for (int i = 0; i < m; i++) {
            int prev = hull[(i - 1 + m) % m];
            int cur = hull[i];
            int next = hull[(i + 1) % m];
            // Edge prev->cur: direction (x[cur]-x[prev], y[cur]-y[prev]), outward normal (y[cur]-y[prev], -(x[cur]-x[prev]))
            double nx1 = y[cur] - y[prev], ny1 = -(x[cur] - x[prev]);
            // Edge cur->next: outward normal
            double nx2 = y[next] - y[cur], ny2 = -(x[next] - x[cur]);
            double a1 = Math.atan2(ny1, nx1);
            double a2 = Math.atan2(ny2, nx2);
            double diff = a2 - a1;
            while (diff < 0) diff += 2 * Math.PI;
            while (diff > 2 * Math.PI) diff -= 2 * Math.PI;
            prob[cur] = diff / (2 * Math.PI);
        }

        for (int i = 0; i < n; i++) System.out.printf("%.9f%n", prob[i]);
    }

    static int[] convexHull(double[] x, double[] y, int n) {
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> x[a] != x[b] ? Double.compare(x[a], x[b]) : Double.compare(y[a], y[b]));
        int[] h = new int[2 * n]; int k = 0;
        for (int i = 0; i < n; i++) { int id = idx[i]; while (k >= 2 && cross(x, y, h[k-2], h[k-1], id) <= 0) k--; h[k++] = id; }
        for (int i = n - 2, t = k + 1; i >= 0; i--) { int id = idx[i]; while (k >= t && cross(x, y, h[k-2], h[k-1], id) <= 0) k--; h[k++] = id; }
        return Arrays.copyOf(h, k - 1);
    }
    static double cross(double[] x, double[] y, int o, int a, int b) {
        return (x[a]-x[o])*(y[b]-y[o])-(y[a]-y[o])*(x[b]-x[o]);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        int idx;
        Point(long x, long y, int idx) {
            this.x = x;
            this.y = y;
            this.idx = idx;
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static long crossVec(long ax, long ay, long bx, long by) {
        return ax * by - ay * bx;
    }

    static long dotVec(long ax, long ay, long bx, long by) {
        return ax * bx + ay * by;
    }

    static List<Point> convexHull(Point[] pts) {
        int n = pts.length;
        if (n <= 1) return new ArrayList<>(Arrays.asList(pts));

        Arrays.sort(pts, (a, b) -> {
            if (a.x != b.x) return Long.compare(a.x, b.x);
            if (a.y != b.y) return Long.compare(a.y, b.y);
            return Integer.compare(a.idx, b.idx);
        });

        ArrayList<Point> lower = new ArrayList<>();
        for (Point p : pts) {
            while (lower.size() >= 2) {
                int m = lower.size();
                if (cross(lower.get(m - 2), lower.get(m - 1), p) <= 0) lower.remove(m - 1);
                else break;
            }
            lower.add(p);
        }

        ArrayList<Point> upper = new ArrayList<>();
        for (int i = n - 1; i >= 0; i--) {
            Point p = pts[i];
            while (upper.size() >= 2) {
                int m = upper.size();
                if (cross(upper.get(m - 2), upper.get(m - 1), p) <= 0) upper.remove(m - 1);
                else break;
            }
            upper.add(p);
        }

        lower.remove(lower.size() - 1);
        upper.remove(upper.size() - 1);
        lower.addAll(upper);
        return lower;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long R = fs.nextLong(); // not actually needed; answer is independent for sufficiently large R

        Point[] pts = new Point[N];
        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            pts[i] = new Point(x, y, i);
        }

        double[] ans = new double[N];

        if (N == 1) {
            ans[0] = 1.0;
        } else {
            Point[] copy = pts.clone();
            List<Point> hull = convexHull(copy);
            int m = hull.size();

            if (m == 1) {
                ans[hull.get(0).idx] = 1.0;
            } else if (m == 2) {
                // All points collinear / only two extreme points matter.
                ans[hull.get(0).idx] = 0.5;
                ans[hull.get(1).idx] = 0.5;
            } else {
                for (int i = 0; i < m; i++) {
                    Point prev = hull.get((i - 1 + m) % m);
                    Point cur = hull.get(i);
                    Point next = hull.get((i + 1) % m);

                    long ax = prev.x - cur.x;
                    long ay = prev.y - cur.y;
                    long bx = next.x - cur.x;
                    long by = next.y - cur.y;

                    double cross = Math.abs((double) crossVec(ax, ay, bx, by));
                    double dot = (double) dotVec(ax, ay, bx, by);

                    double interior = Math.atan2(cross, dot); // in (0, pi)
                    double prob = (Math.PI - interior) / (2.0 * Math.PI);
                    ans[cur.idx] = prob;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            sb.append(String.format(Locale.US, "%.15f%n", ans[i]));
        }
        System.out.print(sb.toString());
    }
}
